<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Biaya', href: '/owner/expenses' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    type Expense = { id: number; kind: string; category: string; description: string; amount_due_rupiah: number; paid_rupiah: number; outstanding_rupiah: number; status: string; incurred_on: string; property: { id: number; name: string } | null; room: { id: number; code: string } | null; maintenance_category: string | null };
    type Page<T> = { data: T[]; links: { url: string | null; label: string; active: boolean }[]; from: number | null; to: number | null; total: number };
    type Property = { id: number; name: string; rooms: { id: number; code: string }[] };
    let { expenses, properties, filters }: { expenses: Page<Expense>; properties: Property[]; filters: { kind: string; property_id: string; status: string } } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
    const label: Record<string, string> = { maintenance: 'Maintenance', operational: 'Operasional', unpaid: 'Belum dibayar', partial: 'Dibayar sebagian', paid: 'Lunas' };
</script>

<AppHead title="Biaya" />
<main class="space-y-6 p-4 md:p-8">
    <header class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Keuangan</p><h1 class="text-3xl font-semibold tracking-tight">Biaya</h1><p class="text-sm text-muted-foreground">Catatan biaya menjadi arus kas keluar hanya setelah pembayaran aktual dicatat.</p></header>
    <section class="space-y-4 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="text-lg font-semibold">Catat kewajiban biaya</h2><p class="text-sm text-muted-foreground">Biaya yang belum dibayar tidak dihitung sebagai kas keluar.</p></div><Form action="/owner/expenses" method="post" class="space-y-4">{#snippet children({ errors, processing })}<div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="property_id" class="text-sm font-medium">Properti</label><select id="property_id" name="property_id" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Pilih properti</option>{#each properties as property (property.id)}<option value={property.id}>{property.name}</option>{/each}</select><InputError message={errors.property_id} /></div><div class="space-y-2"><label for="room_id" class="text-sm font-medium">Kamar (opsional)</label><select id="room_id" name="room_id" class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Area umum / tanpa kamar</option>{#each properties as property (property.id)}<optgroup label={property.name}>{#each property.rooms as room (room.id)}<option value={room.id}>{property.name} · {room.code}</option>{/each}</optgroup>{/each}</select><InputError message={errors.room_id} /></div><div class="space-y-2"><label for="kind" class="text-sm font-medium">Jenis biaya</label><select id="kind" name="kind" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="operational">Operasional</option><option value="maintenance">Maintenance</option></select><InputError message={errors.kind} /></div><div class="space-y-2"><label for="category" class="text-sm font-medium">Kategori</label><Input id="category" name="category" maxlength={100} required placeholder="Contoh: internet, listrik, perbaikan AC" /><InputError message={errors.category} /></div><div class="space-y-2"><label for="amount_due_rupiah" class="text-sm font-medium">Jumlah kewajiban (Rupiah)</label><Input id="amount_due_rupiah" name="amount_due_rupiah" type="number" min={1} step={1} required /><InputError message={errors.amount_due_rupiah} /></div><div class="space-y-2"><label for="incurred_on" class="text-sm font-medium">Tanggal biaya</label><Input id="incurred_on" name="incurred_on" type="date" required /><InputError message={errors.incurred_on} /></div></div><div class="space-y-2"><label for="description" class="text-sm font-medium">Keterangan</label><textarea id="description" name="description" rows={2} maxlength="2000" required class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.description} /></div><InputError message={errors.expense} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Menyimpan…' : 'Simpan biaya'}</Button></div>{/snippet}</Form></section>
    <Form action="/owner/expenses" method="get" class="grid gap-3 rounded-xl border bg-card p-4 sm:grid-cols-4 sm:items-end">{#snippet children({ processing })}<div class="space-y-1"><label for="filter_kind" class="text-sm font-medium">Jenis</label><select id="filter_kind" name="kind" value={filters.kind} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua</option><option value="maintenance">Maintenance</option><option value="operational">Operasional</option></select></div><div class="space-y-1"><label for="filter_property" class="text-sm font-medium">Properti</label><select id="filter_property" name="property_id" value={filters.property_id} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua properti</option>{#each properties as property (property.id)}<option value={property.id}>{property.name}</option>{/each}</select></div><div class="space-y-1"><label for="filter_status" class="text-sm font-medium">Status pembayaran</label><select id="filter_status" name="status" value={filters.status} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua status</option><option value="unpaid">Belum dibayar</option><option value="partial">Dibayar sebagian</option><option value="paid">Lunas</option></select></div><Button type="submit" disabled={processing}>Terapkan filter</Button>{/snippet}</Form>
    <section class="overflow-hidden rounded-xl border bg-card shadow-sm" aria-label="Daftar biaya">{#if expenses.data.length === 0}<div class="p-10 text-center"><h2 class="font-medium">Belum ada biaya</h2><p class="mt-1 text-sm text-muted-foreground">Catatan biaya yang sudah dibuat akan muncul di sini.</p></div>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[58rem] text-left text-sm"><thead class="border-b bg-muted/40 text-muted-foreground"><tr><th class="px-5 py-3 font-medium">Biaya</th><th class="px-5 py-3 font-medium">Lokasi</th><th class="px-5 py-3 font-medium">Tanggal</th><th class="px-5 py-3 font-medium">Status</th><th class="px-5 py-3 text-right font-medium">Kewajiban</th><th class="px-5 py-3 text-right font-medium">Sisa</th><th class="px-5 py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each expenses.data as expense (expense.id)}<tr><td class="px-5 py-4"><p class="font-medium">{expense.category} · {label[expense.kind] ?? expense.kind}</p><p class="mt-1 max-w-sm truncate text-xs text-muted-foreground">{expense.description}</p></td><td class="px-5 py-4"><p>{expense.property?.name ?? '—'}</p><p class="text-xs text-muted-foreground">{expense.room ? `Kamar ${expense.room.code}` : 'Area umum'}</p></td><td class="px-5 py-4">{expense.incurred_on}</td><td class="px-5 py-4">{label[expense.status] ?? expense.status}</td><td class="px-5 py-4 text-right">{money(expense.amount_due_rupiah)}</td><td class="px-5 py-4 text-right font-medium">{money(expense.outstanding_rupiah)}</td><td class="px-5 py-4 text-right"><Link href={`/owner/expenses/${expense.id}`} class="text-primary underline-offset-4 hover:underline">Detail</Link></td></tr>{/each}</tbody></table></div><footer class="flex flex-wrap items-center justify-between gap-4 border-t px-5 py-4 text-sm"><p class="text-muted-foreground">Menampilkan {expenses.from ?? 0}–{expenses.to ?? 0} dari {expenses.total} biaya</p><nav aria-label="Navigasi halaman" class="flex flex-wrap gap-1">{#each expenses.links as link, index (index)}{#if link.url}<Link href={link.url} class={`rounded border px-3 py-1.5 ${link.active ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}>{link.label}</Link>{:else}<span class="rounded border px-3 py-1.5 text-muted-foreground">{link.label}</span>{/if}{/each}</nav></footer>{/if}</section>
</main>
